/* A product shown in its own words in every language (round V8), run after part 136. `product_translation_settings`: one row per product, `show_original` set from Products › Translations › Always show the original; on, the website draws that product's title, description, search engine text and option names as the merchant wrote them in every language, and Storelib AI never translates it. Its translations stay in `site_translations` (part 136) and come back when it is turned off. Server only, as part 136's tables are: the owner writes it through the server, which checks the store is theirs. RLS is on, with one policy that names the store's owner, and no client role is granted the table. No existing row changes. Skips itself with a notice where products, creators or part 136 are not there. Until it runs, the switch says it needs this part and every product reads its translations as before. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.products') IS NULL OR to_regclass('public.creators') IS NULL OR to_regclass('public.site_translations') IS NULL THEN RAISE NOTICE 'product translation settings: products, creators or site_translations is not there yet, run part 136 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.product_translation_settings (product_id uuid PRIMARY KEY REFERENCES public.products(id) ON DELETE CASCADE, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, show_original boolean NOT NULL DEFAULT false, updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL, updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS product_translation_settings_store_original ON public.product_translation_settings (creator_id) WHERE show_original; ALTER TABLE public.product_translation_settings ENABLE ROW LEVEL SECURITY; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'product_translation_settings' AND policyname = 'product_translation_settings_owner') THEN CREATE POLICY product_translation_settings_owner ON public.product_translation_settings FOR ALL TO authenticated USING (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid()))) WITH CHECK (creator_id IN (SELECT id FROM public.creators WHERE user_id = (SELECT auth.uid()))); END IF; REVOKE ALL ON public.product_translation_settings FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_translation_settings TO service_role; END $do$;
notify pgrst, 'reload schema';
